/**
 * Apply Product Improvements Script
 * 
 * This script applies the improvements generated by improve-products.js
 * 
 * Run with: node apply-improvements.js
 */

const fs = require('fs');
const path = require('path');

// Load environment
const envContent = fs.readFileSync(path.join(__dirname, '..', '.env.local'), 'utf8');
const env = {};
envContent.split('\n').forEach(line => {
  const m = line.match(/^([^=]+)=(.*)$/);
  if (m) env[m[1].trim()] = m[2].trim();
});

const DIRECTUS_URL = 'https://zecode-directus.onrender.com';

async function applyImprovements() {
  // Load improvements
  if (!fs.existsSync('product-improvements.json')) {
    console.error('product-improvements.json not found. Run improve-products.js first.');
    process.exit(1);
  }
  
  const improvements = JSON.parse(fs.readFileSync('product-improvements.json', 'utf8'));
  console.log(`Loaded ${improvements.length} product improvements`);
  
  // Authenticate
  const authRes = await fetch(DIRECTUS_URL + '/auth/login', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email: 'zecode@siyaram.com', password: env.DIRECTUS_ADMIN_PASSWORD })
  });
  const token = (await authRes.json()).data.access_token;
  
  let updated = 0;
  let failed = 0;
  
  for (const imp of improvements) {
    try {
      const res = await fetch(`${DIRECTUS_URL}/items/products/${imp.id}`, {
        method: 'PATCH',
        headers: {
          'Authorization': 'Bearer ' + token,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          name: imp.improved.name,
          slug: imp.improved.slug,
          description: imp.improved.description
        })
      });
      
      if (res.ok) {
        updated++;
        if (updated % 25 === 0) {
          console.log(`Progress: ${updated}/${improvements.length} products updated`);
        }
      } else {
        failed++;
        console.error(`Failed to update product ${imp.id}:`, await res.text());
      }
    } catch (err) {
      failed++;
      console.error(`Error updating product ${imp.id}:`, err.message);
    }
  }
  
  console.log(`\n=== COMPLETE ===`);
  console.log(`Updated: ${updated}`);
  console.log(`Failed: ${failed}`);
}

applyImprovements().catch(console.error);
